/* 
This function is integreated in the "constructAlarmAddressSpace" function of the "address_space.js" file of the "node-red-contrib-iiot-opcua" node.
    Allows to make a customize OPC UA address space. If you want to add more variables, add it in variables array following the same pattern:
        {name: 'NameVar', folder: Folderlocation, browseName: 'NameVar', nodeId: 'ns=1;s=VARIdentifier', dataType: DataType.Double/String/Int32/...},
 If yo also want to add a new folder, follow the folders pattern. Be aware with hiercarquy of folders: 
        const NewFolder = namespace.addFolder(SuperiorHierarchyFolder, { browseName: "FolderName" });  
 It can also to be added a view to facilitate the visualization of the variables. Follow the views pattern:  
         { browseName: "ViewName", filter: variable => variable.folder === FolderName },

Author: Jorge Marqués García
*/
function constructAlarmAddressSpace(server, addressSpace, eventObjects, done) {
    const LocalizedText = opcua.LocalizedText;
    const namespace = addressSpace.getOwnNamespace();
    const Variant = opcua.Variant;
    const DataType = opcua.DataType;
    const flexServerInternals = this;

    coreServer.internalDebugLog('init dynamic address space');
    node.warn('construct new address space for OPC UA');

    // Define folders
    const rootFolder = addressSpace.findNode("RootFolder");
    const mySpace = namespace.addFolder(rootFolder.objects, { browseName: "IAXO-ZGZ" });
    const gasFolder = namespace.addFolder(mySpace, { browseName: "GAS" });
    const GasPressure = namespace.addFolder(gasFolder, { browseName: "Pressure" });
    const GasFlow = namespace.addFolder(gasFolder, { browseName: "Flow" });
    const HVFolder = namespace.addFolder(mySpace, { browseName: "HV" });
    const LVFolder = namespace.addFolder(mySpace, { browseName: "LV" });
    const ROOM = namespace.addFolder(mySpace, { browseName: "ROOM" });

    // Define variables
    const variables = [
        { name: 'PT42', folder: GasPressure, browseName: 'PT42', nodeId: 'ns=1;s=PT42', dataType: DataType.Double },
        { name: 'Pinlet', folder: GasPressure, browseName: 'Pinlet', nodeId: 'ns=1;s=Pinlet', dataType: DataType.Double },
        { name: 'Poutlet', folder: GasPressure, browseName: 'Poutlet', nodeId: 'ns=1;s=Poutlet', dataType: DataType.Double },
        { name: 'PVacLine', folder: GasPressure, browseName: 'PVacLine', nodeId: 'ns=1;s=PVacLine', dataType: DataType.Double },
        { name: 'PRpOut', folder: GasPressure, browseName: 'PRpOut', nodeId: 'ns=1;s=PRpOut', dataType: DataType.Double },
        { name: 'Fctrl', folder: GasFlow, browseName: 'Fctrl', nodeId: 'ns=1;s=Fctrl', dataType: DataType.Double },
