        const viewNode = namespace.addView({ organizedBy: rootFolder.views, browseName: view.browseName });
        variables.filter(view.filter).forEach(variable => {
            viewNode.addReference({ referenceType: "Organizes", nodeId: variable.nodeId });
        });
    });

    coreServer.internalDebugLog("create dynamic address space done");
    node.warn("construction of new address space for OPC UA done");

