function parsePrometheusMetrics(text) {
    // Split the text into lines by new line character
    const lines = text.split('\n');

    // Filter out lines starting with the comment character (#)
    const filteredLines = lines.filter(line => !line.trim().startsWith('#'));

    // Create an empty object to store the metrics
    const metrics = {};

    // Split each line into a metric name and value, then add them to the object
    filteredLines.forEach(line => {
        const [metricName, value] = line.trim().split(/\s+/);
        metrics[metricName] = Number(value);
    });

    // Return the JSON object
    return metrics;
}

