// Obtener el estado almacenado en el contexto del nodo
const thresholdAlerts = context.get('thresholdAlerts') || {
    below20: false,
    below15: false,
    below10: false
};

function filterPayloadByMetric(msg, metricNameToFilter) {
    let msg1 = null;
    let msg2 = null;
    let msg3 = null;
    let msg4 = null;

    if (msg.payload.hasOwnProperty(metricNameToFilter)) {
        const metricValue = msg.payload[metricNameToFilter];
        msg1 = { payload: metricValue }; // Mensaje 1 con el valor filtrado

        // Verificar umbrales y enviar mensajes si es necesario
        if (metricValue < 10 && !thresholdAlerts.below10) {
            msg4 = { payload: `Free disk space less than 10GB. Value: ${metricValue}GB` };
            thresholdAlerts.below10 = true;  // Marcar que la alerta ha sido enviada
        }
        if (metricValue < 15 && !thresholdAlerts.below15) {
            msg3 = { payload: `Free disk space less than 15GB. Value: ${metricValue}GB` };
            thresholdAlerts.below15 = true;  // Marcar que la alerta ha sido enviada
        }
        if (metricValue < 20 && !thresholdAlerts.below20) {
            msg2 = { payload: `Free disk space less than 20GB0. Value: ${metricValue}GB` };
            thresholdAlerts.below20 = true;  // Marcar que la alerta ha sido enviada
        }
    }

    // Guardar el estado actualizado en el contexto del nodo
    context.set('thresholdAlerts', thresholdAlerts);

    // Devolver los mensajes (solo los mensajes con contenido se enviarán)
    return [msg1, msg2, msg3, msg4].filter(m => m !== null);
}

